async function loadIcons(names){
 const requested=[...new Set(names)];
 if(requested.some(name=>typeof name!=='string'||!Object.hasOwn(aliases,name)))throw new TypeError('Unknown icon name.');
 const loaded=await Promise.all(requested.map(async name=>[name,(await loaders[aliases[name]]()).default]));
 return Object.fromEntries(loaded);
}
exports.loadIcons=loadIcons;
